CREATE FUNCTION public.pilot_set_pickup_timezone(_distribution uuid,_timezone text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.network_source_access(_distribution,true) OR _timezone NOT IN ('America/New_York','America/Chicago') THEN RAISE EXCEPTION 'Authorized timezone confirmation required';END IF;PERFORM 1 FROM public.trip_distributions WHERE id=_distribution FOR UPDATE;IF EXISTS(SELECT 1 FROM public.provider_trip_offers WHERE distribution_id=_distribution) THEN RAISE EXCEPTION 'Timezone cannot change after offers exist';END IF;UPDATE public.trip_distributions SET pickup_timezone=_timezone WHERE id=_distribution AND selected_workspace_id IS NULL;PERFORM public.network_audit(_distribution,NULL,'pickup_timezone_confirmed',jsonb_build_object('timezone',_timezone));END $$;
CREATE FUNCTION public.pilot_preview_wave(_distribution uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;d public.trip_distributions;radius integer;res jsonb;BEGIN IF NOT public.network_source_access(_distribution,true) THEN RAISE EXCEPTION 'Distribution unavailable';END IF;SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution;SELECT pilot_config INTO c FROM public.trip_network_settings WHERE id=true;radius:=CASE coalesce(d.current_radius,0) WHEN 0 THEN 20 WHEN 20 THEN 50 WHEN 50 THEN 100 WHEN 100 THEN 200 ELSE 200 END;
SELECT jsonb_build_object('radius',radius,'eligible',least(coalesce((c->>'maxCandidates')::int,0),count(*) FILTER(WHERE excluded='' AND public.pilot_scope_reason(d.id,workspace)='')),'excluded',coalesce((SELECT jsonb_object_agg(reason,n) FROM(SELECT reason,count(*) n FROM public.network_acceptance_candidates(d.id,radius,NULL) a CROSS JOIN LATERAL unnest(string_to_array(a.excluded,'; ')) reason WHERE reason<>'' GROUP BY reason)x),'{}'::jsonb),'enabled',public.pilot_scope_reason(d.id,NULL)='' AND radius<=(c->>'maxRadius')::int AND d.selected_workspace_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.provider_trip_offers WHERE distribution_id=d.id AND status IN ('pending','countered','revised') AND expires_at>now()),'reason',public.pilot_scope_reason(d.id,NULL),'timezone',d.pickup_timezone,'geography',d.pickup_area||' → '||d.destination_area,'candidates',CASE WHEN public.has_role(auth.uid(),'admin') THEN coalesce(jsonb_agg(jsonb_build_object('workspace',workspace,'score',score,'explanation',explanation)) FILTER(WHERE excluded=''),'[]'::jsonb) ELSE '[]'::jsonb END) INTO res FROM public.network_acceptance_candidates(d.id,radius,NULL);RETURN res;END $$;
CREATE UNIQUE INDEX IF NOT EXISTS notifications_network_event_dedupe ON public.notifications(user_id,event_key) WHERE event_key IS NOT NULL;
CREATE OR REPLACE FUNCTION public.network_notify(_ws uuid,_type text,_offer uuid,_important boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v text;BEGIN SELECT updated_at::text INTO v FROM public.provider_trip_offers WHERE id=_offer;INSERT INTO public.notifications(user_id,type,title,body,link,event_key) SELECT m.user_id,CASE WHEN _important THEN 'network_important' ELSE 'network_update' END,_type,'Controlled Network status updated. Sign in to review.','/portal/network','network:'||_offer::text||':'||_type||':'||coalesce(v,'event')||':'||m.user_id::text FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND NOT m.is_contractor AND(m.role IN ('owner','admin') OR m.can_manage_trips) AND public.notification_preference_allows(m.user_id,'in_app',_type,true) ON CONFLICT DO NOTHING;END $$;
